#!/usr/bin/env node

/**
 * Campus Clash — Audio Asset Manifest & Licensing Build Validator
 * Enforces zero-tolerance legal compliance for commercial esports release.
 * Verifies that all audio files are indexed, licenses permitted, and credits auto-generated.
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const ROOT_DIR = path.resolve(__dirname, '..');

const MANIFEST_PATH = path.join(ROOT_DIR, 'data', 'audio_manifest.json');
const AUDIO_DIR = path.join(ROOT_DIR, 'assets', 'audio');
const CREDITS_TXT_PATH = path.join(ROOT_DIR, 'CREDITS_AUDIO.txt');
const CREDITS_JSON_PATH = path.join(ROOT_DIR, 'CREDITS_AUDIO.json');

console.log('====================================================');
console.log(' Campus Clash — Audio Manifest & Licensing Validator');
console.log('====================================================\n');

if (!fs.existsSync(MANIFEST_PATH)) {
  console.error(`[FATAL] Audio manifest missing at: ${MANIFEST_PATH}`);
  process.exit(1);
}

const manifest = JSON.parse(fs.readFileSync(MANIFEST_PATH, 'utf-8'));
const allowedLicenses = new Set(manifest.licensePolicy?.allowedLicenses || []);
const forbiddenLicenses = new Set(manifest.licensePolicy?.forbiddenLicenses || []);
const assets = manifest.assets || [];

console.log(`Indexed assets in manifest: ${assets.length}`);
console.log(`Allowed licenses: ${[...allowedLicenses].join(', ')}`);
console.log(`Forbidden licenses: ${[...forbiddenLicenses].join(', ')}\n`);

let hasErrors = false;
const manifestAssetIds = new Set();
const manifestFilenames = new Set();
const attributionEntries = [];

// 1. Validate manifest entries
for (const asset of assets) {
  if (!asset.id) {
    console.error(`[ERROR] Manifest asset missing 'id' field!`);
    hasErrors = true;
    continue;
  }
  if (manifestAssetIds.has(asset.id)) {
    console.error(`[ERROR] Duplicate asset ID detected: ${asset.id}`);
    hasErrors = true;
  }
  manifestAssetIds.add(asset.id);

  if (!asset.filename) {
    console.error(`[ERROR] Asset '${asset.id}' missing 'filename'!`);
    hasErrors = true;
  } else {
    manifestFilenames.add(asset.filename);
  }

  // License checks
  if (!allowedLicenses.has(asset.licenseType)) {
    console.error(`[ERROR] Asset '${asset.id}' has unapproved license: '${asset.licenseType}'!`);
    hasErrors = true;
  }
  if (forbiddenLicenses.has(asset.licenseType)) {
    console.error(`[FATAL] Asset '${asset.id}' has strictly forbidden license: '${asset.licenseType}'!`);
    hasErrors = true;
  }
  if (asset.commercialUseAllowed !== true) {
    console.error(`[ERROR] Asset '${asset.id}' has commercialUseAllowed !== true!`);
    hasErrors = true;
  }

  // Attribution tracking
  if (asset.attributionRequired) {
    attributionEntries.push({
      id: asset.id,
      creator: asset.creator,
      sourceName: asset.sourceName,
      license: asset.licenseType,
      attributionText: asset.attributionText || `${asset.sourceName} by ${asset.creator} (${asset.licenseType})`,
      url: asset.url
    });
  }
}

// 2. Scan audio folder on disk
function scanAudioFiles(dir) {
  let results = [];
  if (!fs.existsSync(dir)) return results;
  const list = fs.readdirSync(dir);
  for (const file of list) {
    const fullPath = path.join(dir, file);
    const stat = fs.statSync(fullPath);
    if (stat && stat.isDirectory()) {
      results = results.concat(scanAudioFiles(fullPath));
    } else {
      const ext = path.extname(file).toLowerCase();
      if (['.wav', '.mp3', '.ogg', '.flac', '.m4a'].includes(ext)) {
        results.push(path.relative(ROOT_DIR, fullPath));
      }
    }
  }
  return results;
}

const filesOnDisk = scanAudioFiles(AUDIO_DIR);
console.log(`Audio binary files found on disk: ${filesOnDisk.length}`);

for (const diskFile of filesOnDisk) {
  if (!manifestFilenames.has(diskFile)) {
    console.error(`[ERROR] Unindexed file found on disk: '${diskFile}'! All files must be declared in audio_manifest.json.`);
    hasErrors = true;
  }
}

// 3. Generate credits files
let creditsText = `# Campus Clash — Audio Attributions & Credits\n`;
creditsText += `# Automatically generated by validate_audio_manifest.js on ${new Date().toISOString()}\n\n`;

if (attributionEntries.length === 0) {
  creditsText += `All sound effects, musical arrangements, and voice syntheses are original procedural works of the Campus Clash development team.\n`;
} else {
  for (const attr of attributionEntries) {
    creditsText += `Asset: ${attr.id}\n`;
    creditsText += `  Source: ${attr.sourceName}\n`;
    creditsText += `  Creator: ${attr.creator}\n`;
    creditsText += `  License: ${attr.license}\n`;
    creditsText += `  URL: ${attr.url}\n`;
    creditsText += `  Attribution: ${attr.attributionText}\n\n`;
  }
}

fs.writeFileSync(CREDITS_TXT_PATH, creditsText, 'utf-8');
fs.writeFileSync(CREDITS_JSON_PATH, JSON.stringify(attributionEntries, null, 2), 'utf-8');
console.log(`Generated attribution credits: ${CREDITS_TXT_PATH}`);

if (hasErrors) {
  console.error('\n❌ Audio manifest validation FAILED with errors! Commercial release blocked.');
  process.exit(1);
} else {
  console.log('\n✅ Audio manifest and licensing verification PASSED! Build cleared.');
  process.exit(0);
}
